146	            BigDecimal total = BigDecimal.ZERO.setScale(2);
147	            boolean[] retired = new boolean[all.size()];
148	            boolean[] held = new boolean[all.size()];
149	            boolean[] active = new boolean[all.size()];
150	            boolean allRetired = true;
151	            for (int i = 0; i < all.size(); i++) {
