155	                held[i] = p != null && today != null && p.heldOn(today);
156	                active[i] = today == null || all.get(i).activeOn(today);
157	                if (active[i]) {
158	                    total = total.add(all.get(i).getShare());
159	                    allRetired &= retired[i];
160	                }
161	            }
162	            boolean balanced = total.compareTo(HUNDRED) == 0;
163	            BigDecimal[] cuts = balanced && pot != null && !allRetired ? cuts(all, retired, held, active, pot) : new BigDecimal[all.size()];
164	            List<PoolMemberView> members = new ArrayList<>();
165	            for (int i = 0; i < all.size(); i++) {
