182	        }
183	
184	        /** Each member's cut of the pot: the pot times their share divided by the shares of the members with a
185	         *  cut added up, rounded half to even to two decimals (0.00 for a retired one or one on hold, whose share is
186	         *  spread over the others in proportion to theirs); the
187	         *  remainder, the pot minus the cuts added up, goes to the member with the smallest non-zero cut, the
188	         *  latest added on a tie (when no cut is non-zero, to the last member with a cut and a share), so the cuts
189	         *  total exactly the pot. When no member has a cut, each is 0.00.
190	         *  A member not active on the sheet's today has none at all. */
191	        private static BigDecimal[] cuts(List<PoolMember> members, boolean[] retired, boolean[] held,
192	                boolean[] active, BigDecimal pot) {
193	            BigDecimal[] cuts = new BigDecimal[members.size()];
194	            BigDecimal shares = BigDecimal.ZERO;
195	            for (int i = 0; i < members.size(); i++) {
196	                if (active[i] && !retired[i] && !held[i]) {
197	                    shares = shares.add(members.get(i).getShare());
198	                }
199	            }
200	            BigDecimal sum = BigDecimal.ZERO.setScale(2);
201	            int smallest = -1;
202	        int last = -1;
203	            for (int i = 0; i < members.size(); i++) {
204	                if (!active[i]) {
205	                    continue;
206	                }
207	                BigDecimal share = members.get(i).getShare();
208	                boolean cut = !retired[i] && !held[i] && shares.signum() > 0;
209	                cuts[i] = cut ? pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN)
210	                        : BigDecimal.ZERO.setScale(2);
211	                sum = sum.add(cuts[i]);
212	                if (cut && share.signum() > 0) {
213	                    last = i;
214	                }
215	                if (cut && cuts[i].signum() != 0
216	                        && (smallest < 0 || cuts[i].compareTo(cuts[smallest]) <= 0)) {
217	                    smallest = i;
218	                }
219	            }
220	            int to = smallest >= 0 ? smallest : last;
221	            if (to >= 0) {
222	                cuts[to] = cuts[to].add(pot.setScale(2).subtract(sum));
223	            }
224	            return cuts;
225	        }
226	    }
