228	    /** The views with each member's cut at the end of each period whose to-date is on or before today, by
229	     *  from-date: its cut in the pools as they stood then (then, by that date). */
230	    static List<PoolView> withHistory(List<PoolView> views, List<Period> periods, LocalDate today,
231	            Function<LocalDate, List<PoolView>> then) {
232	        List<Period> ended = periods.stream()
233	                .filter(p -> today != null && p.getToDate() != null && !p.getToDate().isAfter(today)).toList();
234	        List<List<PoolView>> past = ended.stream().map(p -> then.apply(p.getToDate())).toList();
235	        List<PoolView> out = new ArrayList<>();
236	        for (PoolView v : views) {
237	            List<PoolMemberView> members = new ArrayList<>();
238	            for (PoolMemberView m : v.members()) {
239	                List<PeriodCut> cuts = new ArrayList<>();
240	                for (int i = 0; i < ended.size(); i++) {
241	                    String cut = past.get(i).stream().filter(p -> p.id() == v.id() && p.crew() == v.crew())
242	                            .flatMap(p -> p.members().stream()).filter(m::same).findFirst()
243	                            .map(PoolMemberView::cut).orElse(null);
244	                    cuts.add(new PeriodCut(ended.get(i).getName(), cut));
245	                }
246	                members.add(m.withCuts(cuts));
247	            }
248	            out.add(new PoolView(v.id(), v.name(), members, v.totalShare(), v.balanced(), v.crew()));
249	        }
250	        return out;
251	    }
